bool cmp(pair<int,int>a,pair<int,int>b){
    auto[x1,y1](a);
    auto[x2,y2](b);
    bool p(y1>0 or !y1 and x1>0); //a在上半平面或正x轴
    bool q(y2>0 or !y2 and x2>0); //b在上半平面或正x轴
    if(p!=q) return p>q; //上半平面排前
    else return x1*y2>x2*y1; //同半平面逆时针排序(叉积)
}
signed main(){
