int n,a[N];
int bp[M+1];
vector<int>pri;
void init(){
    iota(bp, bp+M+1, 0);
    for (int x = 2; x <= M; x++){
        if (bp[x] == x) pri.push_back(x);
        for (auto p : pri) {
            if (p * x > M || p > bp[x]) break;
            bp[p * x] = p;
        }
    }
}
int ksm(int a,int b){
    int res=1;
    while(b){
        if(b&1)res=res*a%mod;
        a=a*a%mod;
        b>>=1;
    }
    return res;
}
void solve(){
    cin>>n;
    up(i,1,n){
        cin>>a[i];
    }
    map<int,int>e1,e2;
    up(i,1,n){
        int x=a[i];
        while(x>1){
            int p=bp[x],cnt=0;
            while(x%p==0){
                x/=p;
                cnt++;
            }   
            if(cnt>e1[p])e2[p]=e1[p],e1[p]=cnt;
            else if(cnt>e2[p])e2[p]=cnt;
        }
    }
    int lcm=1;
    for(auto [p,e]:e1)lcm=lcm*ksm(p,e)%mod;
    up(i,1,n){
        int x=a[i],ans=lcm;
        while(x>1){
            int p=bp[x],cnt=0;
            while(x%p==0){
                x/=p;cnt++;
            }   
            if(cnt==e1[p]){
                ans=ans*ksm(ksm(p,cnt-e2[p]),mod-2)%mod;
            }
        }
        cout<<ans<<" ";
    }
    cout<<endl;
}
