    int t=k/g[u].size(),res=k-t*g[u].size();
    priority_queue<int>q;
    for(auto v:g[u])q.push(dfs(v,t));
    if(res){
        while(res--){
            ans+=q.top();
            q.pop();
        }
    }
    return q.top()+a[u];
}
