int nxt[N],n;
inline void getnxt(){
    int len=strlen(s+1),j=0;
    up(i,2,len){
        while(j&&s[i]!=s[j+1])j=nxt[j];
        if(s[j+1]==s[i])j++;
        nxt[i]=j;
    }
}
struct treelca{
    int siz[N],son[N],fa[N],dep[N],top[N];
    inline void dfs1(int u,int from){
        siz[u]=1;son[u]=0;
        dep[u]=dep[from]+1;
        for(auto v:g[u]){
            if(v==from) continue;
            fa[v]=u;dfs1(v,u);
            if(siz[v]>siz[son[u]])son[u]=v;
            siz[u]+=siz[v];
        }
    }
    inline void dfs2(int u,int tp){
        top[u]=tp;
        if(son[u]!=0)dfs2(son[u],tp);
        for(auto v:g[u]){
            if(v==fa[u]||v==son[u]) continue;
            dfs2(v,v);
        }
    }
    inline int lca(int x,int y){
        while(top[x]!=top[y]){
            if(dep[top[x]]>dep[top[y]])x=fa[top[x]];
            else y=fa[top[y]];
        }
        return dep[x]<dep[y]?x:y;
    }
    inline void failtree(){
        dn(i,n,1){
            siz[i]++;
            if(nxt[i])siz[nxt[i]]+=siz[i];
            if(siz[i]>=siz[son[nxt[i]]])son[nxt[i]]=i;
        }
        up(i,1,n){
            dep[i]=dep[nxt[i]]+1;
            if(son[nxt[i]]!=i)top[i]=i;
            else top[i]=top[nxt[i]];
            fa[i]=nxt[i];
        }
    }
