struct ZYFPSGT{
#define ls x<<1
#define rs x<<1|1
    vector<int>mn,tg;
    vector<ul>vr;
    int D,U;
    void build(int x,int l,int r){
        if(l==r)mn[x]=c1[rev[l]];
        else{
            int md=l+r>>1;
            build(ls,l,md),build(rs,md+1,r);
            mn[x]=min(mn[ls],mn[rs]);
        }
    }
    ul mst;
    void atg(int x,int t1,ul t2){
        tg[x]+=t1,mn[x]-=t1,vr[x]^=t2;
    }
