    int ans1=0,ans2=0;
    up(i,l,p)ans1=(ans1+dfs(l,i-1)*dfs(i,p-1)%mod)%mod;
    up(i,p,r)ans2=(ans2+dfs(p+1,i)*dfs(i+1,r)%mod)%mod;
    return f[l][r]=ans1*ans2%mod;
}
