inline int dfs(int n,int m,int k){
	if(n*m==k)return 0;
	if(k<=0)return 0;
	if(f[n][m][k]<inf)return f[n][m][k];
	int res=inf;
	up(i,1,m){
		if(m-i<=0)break;
		res=min(res,dfs(n,i,min(i*n,k))+dfs(n,m-i,max(k-i*n,0))+n*n);
	}
	up(i,1,n){
		if(n-i<=0)break;
		res=min(res,dfs(i,m,min(i*m,k))+dfs(n-i,m,max(k-i*m,0))+m*m);
	}
	return f[n][m][k]=res;
}
