inline int dfs(int u,int sum,int limit,int lead){
    if(u==pos+1)return sum==0;
    if(!limit&&!lead&&~f[u][sum])return f[u][sum];
    int res=0;
    int up=limit?num[u]:9;
    if(u%2==0){
