            if(lead&&!i)res+=dfs(u+1,(i+sum*10)%m,limit&&i==up,1);
            else res+=dfs(u+1,(i+sum*10)%m,limit&&i==up,0);
            res%=mod;
        }
    }
    if(!limit&&!lead)f[u][sum]=res;
    return res;

}
