inline pii dist(int t,int p,int x){
	int sz=g[t].size();
	if(sz==1)return {d(p,g[t][x]),0};
	pii ans={inf,0};
	if(x>0)ans=min(ans,{d(g[t][x-1],p)+n-(g[t][x]-g[t][x-1]),-1});
