	if(x<sz-1)ans=min(ans,{d(g[t][x+1],p)+n-(g[t][x+1]-g[t][x]),1});
	else ans=min(ans,{d(g[t][0],p)+(g[t][sz-1]-g[t][0]),1});
	return ans;
