int n;
int a[N],b[N],cnt[N];
int ans;
void solve(int l, int r) {
	if (r<l||r-l+1<=ans) {
		up(i,l,r)--cnt[a[i]];
		return;
	}
	if(l==r){
		--cnt[a[l]];
		if(b[1]==1)ans=max(ans,1);
		return;
	}
	int p=l,q=r,t=-1,val=b[r-l+1];
	while(p<=q){
		if(cnt[a[p]]<val){t=p;break;}
		if(cnt[a[q]]<val){t=q;break;}
		++p,--q;
	}
	if(t<0){
		ans=max(ans,r-l+1);
		up(i,l,r)--cnt[a[i]];
		return;
	}
	int mid=(l+r)>>1;
	if(t<=mid){
		up(i,l,t)--cnt[a[i]];
		solve(t+1,r);
		up(i,l,t-1)++cnt[a[i]];
		solve(l,t-1);
	} 
	else{
		up(i,t,r)--cnt[a[i]];
		solve(l,t-1);
		up(i,t+1,r)++cnt[a[i]];
		solve(t+1,r);
	}
}
