inline int ask(int k,int l,int r,db maxx){
    if(maxl[k]<=maxx)return 0;
    if(l==r)return maxl[k]>maxx;
    int mid=(l+r)>>1;
    if(maxl[lc]<=maxx)return ask(rc,mid+1,r,maxx);
    return ask(lc,l,mid,maxx)+ans[k]-ans[lc];
