inline int clac(int u){
	if(del[u])return 0;
	int res=0;
	getwc(u,0,getsiz(u,0),u);
	del[u]=1;
	vector<int>p;
	for(auto [v,w]:g[u]){
		if(del[v])continue;
		vector<int>q;
